import{_ as a,o,c as r,a2 as e}from"./chunks/framework.A5mep7Fe.js";const u=JSON.parse('{"title":"⚙️ 03 · C / C++（推理引擎与高性能）","description":"","frontmatter":{},"headers":[],"relativePath":"06-开发岗-编程语言与工程/03-C-Cpp.md","filePath":"06-开发岗-编程语言与工程/03-C-Cpp.md","lastUpdated":1786806808000}'),l={name:"06-开发岗-编程语言与工程/03-C-Cpp.md"};function n(i,t,s,p,c,d){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="⚙️-03-·-c-c-推理引擎与高性能" tabindex="-1">⚙️ 03 · C / C++（推理引擎与高性能） <a class="header-anchor" href="#⚙️-03-·-c-c-推理引擎与高性能" aria-label="Permalink to &quot;⚙️ 03 · C / C++（推理引擎与高性能）&quot;">​</a></h1><blockquote><p>大模型的「底层命脉」：推理引擎（TensorRT/vLLM 内核）、算子优化、嵌入式端侧都靠 C/C++。算法岗做训练框架、开发岗做高性能服务都受益。</p></blockquote><hr><h2 id="一、核心考点" tabindex="-1">一、核心考点 <a class="header-anchor" href="#一、核心考点" aria-label="Permalink to &quot;一、核心考点&quot;">​</a></h2><ul><li><strong>内存管理</strong>：栈/堆、指针、野指针、内存泄漏（valgrind/ASan）。</li><li><strong>RAII（C++）</strong>：用对象生命周期管理资源，异常安全。</li><li><strong>智能指针</strong>：unique_ptr / shared_ptr / weak_ptr。</li><li><strong>引用 vs 指针</strong>、移动语义（std::move）、拷贝消除。</li><li><strong>并发</strong>：std::thread、原子操作、锁、无锁结构。</li><li><strong>虚函数/多态</strong>、对象模型、虚表。</li></ul><h2 id="二、ai-结合点" tabindex="-1">二、AI 结合点 <a class="header-anchor" href="#二、ai-结合点" aria-label="Permalink to &quot;二、AI 结合点&quot;">​</a></h2><ul><li><strong>推理引擎开发</strong>：TensorRT、ONNX Runtime、vLLM 的 CUDA kernel。</li><li><strong>算子优化</strong>：算子融合、量化 kernel、FlashAttention 实现。</li><li><strong>高性能服务</strong>：用 C++ 写低延迟推理网关/批处理。</li><li><strong>端侧部署</strong>：手机/NPU 上的模型推理（NCNN/MNN）。</li></ul><h2 id="三、面试侧重" tabindex="-1">三、面试侧重 <a class="header-anchor" href="#三、面试侧重" aria-label="Permalink to &quot;三、面试侧重&quot;">​</a></h2><ul><li>算法岗：常考「手撕」数据结构/算法（见 <code>09-面试实战/高频手撕代码题</code>），C++ 实现。</li><li>开发岗：考内存安全、并发、性能优化意识。</li></ul><h2 id="四、高频追问" tabindex="-1">四、高频追问 <a class="header-anchor" href="#四、高频追问" aria-label="Permalink to &quot;四、高频追问&quot;">​</a></h2><p><strong>Q1：shared_ptr 有什么坑？</strong></p><blockquote><p>循环引用导致内存泄漏（用 weak_ptr 打破）；引用计数有原子开销；大对象传递建议用移动而非拷贝。</p></blockquote><p><strong>Q2：C++ 怎么避免内存泄漏？</strong></p><blockquote><p>优先 RAII + 智能指针；明确所有权；用 ASan/valgrind 检测；资源获取即初始化。</p></blockquote><p><strong>Q3：为什么推理引擎多用 C++？</strong></p><blockquote><p>对硬件（GPU/NPU）控制和性能极致优化能力最强，零成本抽象，适合低延迟、高吞吐的推理与算子实现。</p></blockquote><hr><p>➡️ 下一步：<a href="./04-Go">04-Go</a></p>',18)])])}const g=a(l,[["render",n]]);export{u as __pageData,g as default};
